#!/usr/bin/env python3
"""Generate read-only checks for reviewed Mosey rules, not whole-policy hashes."""
import argparse
from pathlib import Path
from project_paths import ASSETS
from build_module import asset_path, require_asset_file
import re
import shlex
import tempfile

BASE = ASSETS / 'research/extracted/ColorOS'
RULE_FILES = [
    'vendor/etc/selinux/vendor_sepolicy.cil',
    'system_ext/etc/selinux/system_ext_sepolicy.cil',
    'system_ext/etc/selinux/mapping/202504.cil',
]
HEAD = '''#!/system/bin/sh
# Generated by scripts/generate_compatibility.py. Read-only prerequisite checks.
# Single-line CIL format is expected, as in the reviewed stock firmware.
mosey_require_line() {
    if ! awk -v wanted="$2" '
        { gsub(/[[:space:]]+/, " "); sub(/^ /, ""); sub(/ $/, ""); if ($0 == wanted) found=1 }
        END { exit !found }
    ' "$1"; then
        echo "MISSING prerequisite in $1: $2"
        return 1
    fi
}

mosey_require_member() {
    if ! awk -v attr="$2" -v member="$3" '
        /^\\(typeattributeset / {
            gsub(/[()]/, " ")
            if ($2 != attr) next
            positive=1; present=0
            for (i=3; i<=NF; i++) {
                if ($i == "and" || $i == "or" || $i == "not" || $i == "xor" || $i == "all") positive=0
                if ($i == member) present=1
            }
            if (positive && present) found=1
        }
        END { exit !found }
    ' "$1"; then
        echo "MISSING membership in $1: $2 contains $3"
        return 1
    fi
}

mosey_check_compatibility() {
    compatibility_ok=true
'''


def generate(output=None):
    output = asset_path(output or ASSETS / 'build/generated/compatibility.sh')
    if output.exists() and not output.is_file():
        raise ValueError('Compatibility output must be a regular file inside moseyPLK-assets.')
    checks = set()
    for rel in RULE_FILES:
        source = require_asset_file(BASE / rel, 'local ColorOS configuration ' + rel)
        for raw in source.read_text().splitlines():
            line = ' '.join(raw.split())
            if 'mosey' not in line or not line.startswith('('):
                continue
            tokens = re.findall(r'[^()\s]+', line)
            if tokens[0] in {'type', 'typeattribute', 'roletype', 'allow', 'allowx', 'typetransition', 'expandtypeattribute'}:
                checks.add(('mosey_require_line', '/' + rel, line))
            elif tokens[0] == 'typeattributeset':
                # Named positive memberships only; ignore generated neverallow
                # bookkeeping whose indices can change for unrelated reasons.
                if tokens[1].startswith('base_typeattr_'):
                    continue
                if 'mosey' in tokens[1]:
                    checks.add(('mosey_require_line', '/' + rel, line))
                else:
                    assert not set(tokens[2:]) & {'and', 'or', 'not', 'xor', 'all'}
                    for token in tokens[2:]:
                        if 'mosey' in token:
                            checks.add(('mosey_require_member', '/' + rel, tokens[1], token))
    for rel in [
        'vendor/etc/selinux/vendor_file_contexts',
        'vendor/etc/selinux/vendor_service_contexts',
        'system_ext/etc/selinux/system_ext_seapp_contexts',
        'system_ext/etc/sysconfig/hidden-api-whitelist-ext.xml',
    ]:
        source = require_asset_file(BASE / rel, 'local ColorOS configuration ' + rel)
        for raw in source.read_text().splitlines():
            line = ' '.join(raw.split())
            if 'mosey' not in line or line.startswith('#') or 'Package:' in line:
                continue
            checks.add(('mosey_require_line', '/' + rel, line))
    if not checks:
        raise ValueError('No reviewed Mosey prerequisites found; refusing to generate an empty check.')
    body = ''.join('    ' + ' '.join(shlex.quote(arg) for arg in check) + ' || compatibility_ok=false\n'
                   for check in sorted(checks))
    tail = f'''    [ "$compatibility_ok" = true ] || return 1
    echo 'OK: {len(checks)} reviewed Mosey prerequisites'
}}
'''
    output.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile(mode='w', encoding='utf-8', dir=output.parent,
                                     prefix='.compatibility-', delete=False) as temporary:
        temporary.write(HEAD + body + tail)
        pending = Path(temporary.name)
    try:
        asset_path(output)
        pending.replace(output)
    finally:
        pending.unlink(missing_ok=True)
    print(f'Generated {len(checks)} focused checks in {output}')
    return output


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', type=Path,
                        help='Generated shell path inside ignored moseyPLK-assets (default: build/generated/compatibility.sh)')
    args = parser.parse_args()
    try:
        generate(args.output)
    except (ValueError, OSError) as error:
        raise SystemExit(str(error)) from error
